def main():
    n, m = map(int, input().split())
    E = [tuple(map(int, input().split())) for _ in range(m)]
    adj = [[] for _ in range(n + 1)]
    for a, b in E: adj[a].append(b); adj[b].append(a)
    d = [-1] * (n + 1); d[1] = 0; q = [1]
    for u in q:
        for v in adj[u]:
            if d[v] < 0: d[v] = d[u] + 1; q.append(v)
    d = d[1:]
    print(max(x for x in d if x >= 0))

